"""Full carrot methods and their recovered sauce components."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'carrot-candidates.json').read_text(encoding='utf-8'))
rows.append(dict(id='historical-c1c96873c42e90b6062c3724'))
records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Use the same weight of caster sugar.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes,category='Side dishes'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
def parsley(a=5):return I('parsley',a,'g','fresh parsley, finely chopped','Use the same weight of chives, or omit.')
def milk(a):return I('milk',a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.')
def rice(a):return I('rice',a,'g','uncooked long-grain white rice','Use the same weight of another white rice; follow its cooking time until tender.')
def eggfinish():return ['Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in a little hot soup, then return the mixture to the saucepan.','Stir over low heat until the soup reaches 71°C (160°F), without boiling. Serve promptly.']
def lemon(a,k='lemon'):return I(k,a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
def bay():return I('bay',1,'','dried bay leaf','Omit if unavailable.')
def lard(a):return I('lard',a,'g','food-grade pork lard','Use the same weight of neutral vegetable oil.')
def tk(k):return '{{'+k+'}}'
def roux(prefix,b,f,liquid,liquidname='unsalted prepared chicken stock'):
 return [dict(butter(b),key=prefix+'butter'),dict(flour(f),key=prefix+'flour'),I(prefix+'stock',liquid,'ml',liquidname,'Use the same volume of unsalted vegetable stock; flavor differs.')]
def rouxsteps(p):
 return ['In a separate small saucepan, melt '+tk(p+'butter')+'. Stir in '+tk(p+'flour')+' and cook for 2 minutes without browning. Gradually whisk in '+tk(p+'stock')+' until smooth. Simmer gently for 5 minutes, stirring.']
def veloute(prefix='s',volume=120):
 # A small complete mushroom sauce component, with all output used in its parent.
 q=volume/120
 return roux(prefix,10*q,8*q,120*q)+[I(prefix+'mushroom',25*q,'g','cultivated white mushrooms, finely chopped','Use the same weight of cultivated cremini mushrooms.')]
def veloutesteps(p='s'):
 return ['Melt '+tk(p+'butter')+' in a small pan. Add '+tk(p+'mushroom')+' and cook gently for 5 minutes without browning. Stir in '+tk(p+'flour')+' for 2 minutes, then gradually whisk in '+tk(p+'stock')+'. Simmer for 10 minutes, stirring, until smooth. Press through a fine sieve, discard the mushroom pieces and keep the sauce warm.']

def peas(a):return I('peas',a,'g','shelled green peas, fresh or frozen','Use the same weight of frozen peas, adding them without thawing.')
def cornflour(a):return I('cornflour',a,'g','cornstarch (cornflour)','Use the same weight of arrowroot starch, adding it near the end and heating just until thickened.')
def nutmeg():return I('nutmeg',.125,'tsp','ground nutmeg','Use the same amount of ground mace, or omit.')
def boilsteps(shape='1 cm cubes',time='12–18'):
 return ['Cut {{carrot}} into '+shape+'. Bring {{water}} and {{salt}} to a boil. Add the carrots and simmer for '+time+' minutes until tender when pierced with a fork. Drain well.']

def eggs(a):return I('eggs',a,'','large eggs','Use 50 g pasteurized liquid whole egg per egg only where the eggs do not need to be separated.')
def garlic(a):return I('garlic',a,'g','peeled garlic, finely minced','Use half the weight of garlic paste without added salt.')
def thyme(a=2):return I('thyme',a,'g','fresh thyme leaves','Use 0.25 tsp dried thyme per 2 g fresh.')
def vinegar(a):return I('vinegar',a,'ml','white wine vinegar','Use the same volume of apple cider vinegar.')
def chicken(a):return I('chicken',a,'g','raw bone-in chicken pieces','Use the same weight of bone-in turkey pieces; cook to at least 74°C (165°F) and until tender.')
def duck(a):return I('duck',a,'g','raw bone-in duck pieces, trimmed of excess skin and fat','Use the same weight of duck legs; cook until tender and at least 74°C (165°F).')
def beef(a):return I('beef',a,'g','boneless beef chuck, trimmed','Use the same weight of boneless beef shin; allow additional simmering time until tender.')

r=add(19,'Nákyp z Mrkve (Carrot and Marrow Soufflé)',6,75,'Finely grated carrots, marrow and breadcrumbs make a lightly sweet spiced soufflé, lifted with beaten egg whites.',[carrot(350),salt(2),I('marrow',60,'g','food-grade beef marrow, removed from bones and finely minced','Use the same weight of softened unsalted butter for a marrow-free variation.'),eggs(6),sugar(60),I('crumbs',100,'g','plain dry breadcrumbs','Use the same weight of plain wheat bread dried and finely grated.'),I('allspice',.25,'tsp','ground allspice','Use the same amount of cinnamon for a different flavor.'),nutmeg(),I('fennel',.125,'tsp','ground fennel seed','Omit if unavailable.'),I('grease',5,'g','softened unsalted butter for the dish','Use the same weight of a block-style dairy-free butter alternative.'),I('coating',10,'g','plain dry breadcrumbs for the dish','Use the same weight of fine plain cracker crumbs.'),I('finishsugar',5,'g','caster sugar for serving','Omit for a less sweet finish.')],['Heat the oven to 175°C (350°F). Grease a 1.5-liter soufflé dish with {{grease}} and coat it with {{coating}}. Finely grate {{carrot}} and mix with {{salt}}.','Separate {{eggs}} into yolks and whites, keeping the whites in a clean grease-free bowl. Beat {{marrow}} with {{sugar}} until evenly combined, then beat in the yolks one at a time.','Stir in the carrots, {{crumbs}}, {{allspice}}, {{nutmeg}} and {{fennel}}. Beat the reserved whites to firm peaks and fold into the mixture in three additions, retaining as much air as possible.','Spoon into the prepared dish, leaving at least 3 cm of headroom. Bake for 40–50 minutes until risen, set in the center and at least 74°C (165°F) in the middle. Use additional dishes if scaling up.','Sprinkle with {{finishsugar}} and serve immediately in the baking dish; the soufflé will settle as it cools.'],'The original page380 says 6 dekagrams of rubbed marrow, not 6 dekagrams of grated carrot. This correction retains marrow at60g. Carrot and breadcrumb weights, pan size and oven settings are modern choices. Folding whites in last replaces the source half-hour warm-water stirring, which would lose their aeration. Butter replaces tallow only for greasing. A butter substitution for marrow is offered explicitly; the base is not vegetarian.','Main dishes')
next(i for i in r['ingredients'] if i['key']=='eggs')['substitution']='Use six large pasteurized shell eggs if preferred; the whites must remain separate and able to whip.'
r['source']+=' Primary scan checked: Česká kuchařka recipe1366, printed page380, Internet Archive leaf386.'

r=add(20,'Skopové s Mrkví (Mutton Ribs with Carrots)',6,190,'Tender mutton ribs and carrot strips are brought together in a light roux-thickened broth with a small caramel finish.',[I('mutton',1500,'g','raw mutton ribs cut into manageable sections','Use the same weight of lamb ribs; begin checking tenderness earlier.'),water(2500),salt(6),onion(150),celery(100),parsley(10),carrot(800),butter(40),pepper(),sugar(13),flour(20),I('caramel',8,'g','granulated sugar for the caramel finish','Omit this small finishing caramel if preferred.'),water(30,'caramelwater'),I('brothportion',600,'ml','strained mutton cooking broth reserved in the steps','Use the same volume of unsalted prepared beef stock if necessary.')],['Put {{mutton}} in a stockpot with {{water}}, {{salt}}, quartered {{onion}}, roughly chopped {{celery}} and {{parsley}}. Bring to a simmer, skim the foam and cook gently for 2–2½ hours until the meat is tender and pulls easily from the bone. Keep the meat submerged with extra hot water as needed.','Lift out the ribs and keep covered and hot. Strain the broth and skim surface fat. Measure {{brothportion}}; cool any unused broth promptly in shallow containers and refrigerate for another use.','Cut {{carrot}} into strips about 5 mm thick. Melt {{butter|0.65}} in a wide saucepan, add the carrots, {{pepper}}, {{sugar}} and the measured broth. Cover loosely and simmer for 20–30 minutes until tender.','Melt {{butter|0.35}} in a small pan, stir in {{flour}} and cook for 2 minutes. Gradually whisk in several spoonfuls of hot carrot broth, then stir the smooth roux mixture back into the carrots. Simmer for 5 minutes.','In a separate small pan, heat {{caramel}} with {{caramelwater|0.3333333333333333}} until pale amber. Take off the heat and carefully add {{caramelwater|0.6666666666666667}}, keeping your hands back from the steam. Stir until dissolved, then add to the carrots.','Add the cooked ribs and simmer gently for 5–10 minutes until everything is hot. Remove any loose bones before serving.'],'Salted ribs are interpreted as fresh ribs seasoned before simmering, not commercially cured ribs. The undefined stock vegetables become onion, celery and parsley. Meat, carrot, broth and roux weights are modern choices; the source caramel is retained as a small measured finish. The alternative cabbage preparations are named variations.','Main dishes')
for id,label,fraction in [('cabbage','Mutton with cabbage',0),('mixed','Mutton with carrots and cabbage',.5)]:
 its=[copy.deepcopy(i) for i in r['ingredients'] if i['key']!='carrot']+([I('carrot',800,'g','trimmed white cabbage','Use the carrot base version instead.')] if not fraction else [carrot(400),I('cabbage',400,'g','trimmed white cabbage','Use the same weight of Savoy cabbage.')])
 st=[t.replace('carrots','vegetables').replace('carrot broth','vegetable broth') for t in r['steps']];st[2]=st[2].replace('Cut {{carrot}} into strips about 5 mm thick.','Cut {{carrot}} into5mm strips and {{cabbage}} into small wedges.' if fraction else 'Cut {{carrot}} into small wedges.')
 variant(r,id,label,its,st)

r=add(25,'Pato con Zanahoria (Duck and Carrot Braise)',6,125,'Duck pieces brown in butter, then simmer with carrot rounds in a lightly thickened cooking broth.',[duck(1800),butter(70),salt(5),carrot(600),flour(8),water(900),pepper()],['Pat {{duck}} dry and season with {{salt}}. Melt {{butter|0.8}} in a heavy casserole over medium heat. Brown the duck in batches, skin side first, for 8–10 minutes per batch, keeping the butter from burning. Lift the pieces onto a plate.','Pour off excess rendered fat, leaving a thin coating in the casserole. In a small saucepan, melt {{butter|0.2}}, stir in {{flour}} and cook for 2 minutes. Gradually whisk in {{water}} until smooth.','Return the duck to the casserole, pour over the flour mixture and add {{pepper}}. Bring to a gentle simmer, cover loosely and cook for 35–45 minutes, turning once.','Cut {{carrot}} into 1 cm rounds and add to the casserole. Simmer for another 25–35 minutes until the carrots and duck are tender and the thickest duck flesh reaches at least 74°C (165°F), avoiding bone. Add hot water if the sauce becomes too thick.','Skim excess surface fat and serve hot. If using mixed duck cuts, remove any breast pieces that finish early and return them just before serving.'],'Four spoonfuls of butter become56g, with14g separately supplied for the flour roux. Duck, carrot and water amounts are modern choices. Carrots are added later than in the brief source so they retain their shape while the duck tenderizes.','Main dishes')

r=add(30,'Pollos con Zanahoria, Ham and Chorizo',6,90,'Chicken and carrots braise with ham, chorizo and warm spices, finished with sherry, chiles, olives and capers.',[chicken(1500),I('ham',100,'g','fully cooked ham, diced','Use the same weight of fully cooked smoked turkey.'),I('chorizo',150,'g','firm cured chorizo labeled ready to eat, sliced','Use the same weight of fully cooked smoked sausage; fresh raw chorizo needs separate cooking before use.'),carrot(500),lard(15),thyme(),water(600),oil(10),I('clove',.125,'tsp','ground cloves','Omit for a milder stew.'),I('cinnamon',.25,'tsp','ground cinnamon','Use half the amount of ground allspice for a different flavor.'),pepper(),I('sherry',30,'ml','dry sherry','Use25ml unsalted chicken stock plus5ml white wine vinegar for an alcohol-free variation.'),I('chiles',30,'g','drained pickled jalapeño slices','Use the same weight of roasted sweet pepper for a mild garnish.'),I('olives',60,'g','pitted green olives, drained','Use the same weight of pitted black olives.'),I('capers',15,'g','capers, rinsed and drained','Use the same weight of finely chopped cornichons.')],['Heat {{lard}} in a wide casserole. Pat {{chicken}} dry and brown in batches for 8–10 minutes per batch. Add {{ham}}, {{chorizo}}, {{thyme}} and {{carrot}} cut in 1 cm rounds; cook, turning, for 3 minutes.','Add {{water}}, {{oil}}, {{clove}}, {{cinnamon}} and {{pepper}}. Bring to a simmer, cover loosely and cook for 35–50 minutes until the chicken is tender and reaches at least74°C (165°F) in the thickest flesh away from bone. Add water if needed to prevent drying.','Stir in {{sherry}} and heat for 2 minutes. Skim excess surface fat. Spoon onto a platter and garnish with {{chiles}}, {{olives}} and {{capers}}. Serve hot.'],'Every amount beyond the spoonful of lard is supplied as a modern domestic batch. Firm ready-to-eat chorizo and cooked ham are explicit product choices; the source does not identify whether its sausage was raw or cured. No extra salt is added because the meats and garnishes are salty. Sherry remains alcoholic after cooking.','Main dishes')

r=add(42,'Frango Ensopado com Cenouras (Chicken Stew with Carrots)',6,100,'Chicken and carrots simmer in a lightly tangy broth thickened with butter and flour and finished with a gently cooked yolk.',[chicken(1500),water(1200),carrot(600),parsley(10),flour(12),butter(28),vinegar(15),sugar(6),yolks(1),salt(4)],['Put {{chicken}} in a casserole with {{water}} and {{salt}}. Bring slowly to a simmer, skim foam and cook gently for25–30 minutes.','Cut {{carrot}} into1cm rounds and add with {{parsley}} and {{vinegar}}. Mash softened {{butter}} with {{flour}} until smooth, loosen with a few spoonfuls of hot broth and stir into the casserole.','Simmer for25–35 minutes, stirring carefully, until the carrots are tender, the flour is cooked and the chicken reaches at least74°C (165°F) in the thickest flesh away from bone. Add water if necessary to keep a loose sauce.','Stir in {{sugar}}. Whisk {{yolks}} in a bowl, gradually whisk in a little hot broth, then return to the casserole over low heat. Stir until the sauce reaches74°C (165°F), without boiling, and serve promptly.'],'The two unspecified source chickens become one measured1.5kg batch. The source initial boiling water and later four cups are replaced by one explicit1.2liter starting liquid to avoid an undefined stock component. Missing carrot, salt and flour quantities are supplied. The egg finish is tempered and heated, not stirred in raw at serving.','Main dishes')

r=add(43,'Lombo Estufado with Carrots and Reduced Beef Jus',6,95,'Beef loin cooks gently with small carrots, then rests while its cooking juices are strained, skimmed and reduced.',[I('loin',1200,'g','boneless beef sirloin roast, tied into an even shape','Use the same weight of a beef tenderloin roast; begin checking its temperature earlier.'),carrot(600),oil(20),stock(600),salt(5),pepper()],['Heat the oven to160°C (320°F). Pat {{loin}} dry and season with {{salt}} and {{pepper}}. Heat {{oil}} in an oven-safe lidded casserole and brown the beef on all sides for8–10 minutes.','Add {{stock}}, scraping up the browned juices. Add {{carrot}}, choosing slender carrots left whole or thick ones halved lengthwise. Baste the beef and carrots with the liquid and cover.','Cook in the oven for45–70 minutes, basting once, until the beef reaches at least63°C (145°F) in the center. Check early and remove the beef when ready; let it rest at least3 minutes, preferably10, loosely covered. If the carrots need longer, continue cooking them in the covered casserole until tender.','Lift the carrots onto a warm platter. Strain the cooking liquid through a fine sieve into a saucepan, skim off excess fat and simmer until reduced to about half its starting volume.','Slice the rested beef and arrange beside the carrots. Spoon a little jus over both and serve the rest separately.'],'The source only gives beef loin, carrots and an as-usual braise. This is a disclosed complete modern preparation using prepared stock, measured seasoning, a gentle oven and a thermometer endpoint rather than a long stew that would dry lean loin. The strained reduced cooking jus supplies the missing meat essence; it is not claimed to reproduce an unidentified historical stock formula.','Main dishes')

r=add(44,'Pato Refogado com Cenouras (Lemon-Brandy Duck)',6,310,'Duck is marinated with lemon and garlic, browned in butter and braised with carrots and a little brandy.',[duck(1800),salt(5),pepper(),lemon(45),garlic(12),butter(25),water(600),I('brandy',45,'ml','brandy','Use the same volume of unsalted chicken stock for an alcohol-free variation.'),flour(4),carrot(600)],['Mix {{salt}}, {{pepper}}, {{lemon}} and {{garlic}} in a food-safe container. Add {{duck}}, turn to coat, cover and marinate for3 hours in the refrigerator at4°C (40°F) or colder.','Lift out the duck and pat dry; discard the used marinade. Melt {{butter}} in a heavy casserole over medium heat and brown the duck in batches for8–10 minutes per batch. Pour off excess rendered fat.','Take the casserole away from any flame. Stir in {{flour}}, then carefully add {{brandy}} and {{water}}. Return to the heat, bring to a simmer and cover loosely.','Simmer for35–45 minutes. Add {{carrot}} cut into1cm rounds and cook for25–35 minutes more, until the duck and carrots are tender and the thickest duck flesh reaches at least74°C (165°F), avoiding bone. Add water if the sauce reduces too far.','Skim surface fat and serve hot. Remove any breast pieces that cook earlier than the legs and return them just before serving.'],'The original paragraph lists salt, pepper, lemon and garlic for the marinade, then refers to it as vinho velho without separately adding wine. This adaptation uses the explicitly listed marinade and does not invent a wine quantity. The later aguardente becomes45ml brandy; the undefined cup of water is deliberately increased to600ml for a workable covered braise. Carrots are added later for texture. Discarding marinade and refrigerated holding are modern handling choices. Brandy remains alcoholic after cooking.','Main dishes')

r=add(45,'Cinouras de Tigelada (Sweet-Tart Carrot and Egg Bake)',6,85,'Batter-fried carrots are layered with a sweet-tart herb sauce and baked under beaten eggs until golden.',[carrot(750),water(1500),salt(4),flour(100),water(130,'batterwater'),oil(120),butter(40),parsley(10),I('cilantro',5,'g','fresh cilantro, chopped','Use the same weight of parsley for a different flavor.'),onion(150),I('mint',3,'g','fresh mint leaves, chopped','Omit if unavailable; oregano is not an equivalent flavor.'),vinegar(30),I('cinnamon',.25,'tsp','ground cinnamon','Use the same amount of ground allspice for a different flavor.'),I('honey',25,'g','honey','Use20g granulated sugar plus5ml water.'),water(100,'saucewater'),eggs(6)],['Heat the oven to180°C (355°F). Cut {{carrot}} into quarters lengthwise, shortening very long pieces. Bring {{water}} and {{salt}} to a boil and simmer the carrots for12–18 minutes until just tender. Drain and pat dry.','Whisk {{flour}} with {{batterwater}} to make a smooth coating batter. Heat {{oil}} in a wide skillet over medium heat. Dip the carrots in the batter, let excess drip away and fry in batches for3–4 minutes per side until the coating is golden. Drain on a rack and arrange in a shallow2liter baking dish.','Melt {{butter}} in a clean pan. Add finely chopped {{onion}} and soften for8–10 minutes. Add {{parsley}}, {{cilantro}}, {{mint}}, {{vinegar}}, {{cinnamon}}, {{honey}} and {{saucewater}}. Simmer for5 minutes and spoon evenly over the carrots.','Beat {{eggs}} until evenly combined and pour over the carrots and sauce. Bake for20–30 minutes until set in the center, golden on top and at least71°C (160°F) in the egg layer. Rest for5 minutes, then serve.'],'The original pages128–129 were visually checked. Polme de farinha is a flour batter, not dry flour dusting; hortelã is mint, not oregano. The omitted final line specifies SIX BEATEN EGGS and gentle heat above and below until browned. A conventional oven supplies that finish. Repeated parsley names are combined, and missing amounts, batter liquid and sauce water are modern choices.','Main dishes')
r['source']+=' Primary scan verified: Arte de cozinha, printed pages128–129, Internet Archive leaves130–131.'

r=add(86,'Stewed Steak with Carrots, Turnips and Saffron',4,165,'Braising steak cooks slowly with carrot, turnip and onion, then receives a light saffron-scented thickening.',[beef(800),carrot(200),turnip(400),onion(150),salt(4),pepper(),nutmeg(),water(900),flour(3),I('saffron',.05,'g','saffron threads','Omit if unavailable; turmeric changes the flavor and is not an equivalent substitute.'),water(30,'slurrywater')],['Cut {{beef}} into four thick portions. Put in a saucepan with {{water}}, {{salt}}, {{pepper}} and {{nutmeg}}. Bring to a gentle simmer, skim foam, cover loosely and cook for90 minutes.','Cut {{carrot}} and {{turnip}} into pieces about5cm long and1cm thick; cut {{onion}} into wedges. Add the vegetables to the beef and simmer for40–60 minutes until both meat and vegetables are tender, adding hot water if needed.','Crush {{saffron}} and mix with a spoonful of hot broth in a small bowl; let steep for5 minutes. Whisk {{flour}} with {{slurrywater}} until smooth.','Stir the saffron mixture and flour slurry into the stew. Simmer for5–7 minutes, stirring, until the flour is cooked. Serve hot.'],'Braising steak is explicitly chosen as chuck rather than a quick-cooking tender steak. Missing meat, liquid and vegetable weights are supplied; vegetables are added after the initial meat simmer to preserve their shape. The source small teaspoon of flour gives only light thickening.','Main dishes')

r=add(90,'Boiled Beef with Carrot-Cream Sauce',6,200,'Gently simmered beef is served with a smooth sauce of carrots, aromatics, butter and cream.',[beef(1200),water(2500),salt(6),carrot(600),onion(200),celery(100),parsley(5),thyme(),butter(14),cream(120),pepper()],['Put {{beef}} in a stockpot with {{water}} and {{salt}}. Bring slowly to a simmer, skim the foam, cover loosely and cook for2–2½ hours until nearly tender. Add water if needed to keep the beef submerged.','Add {{carrot}} cut in chunks, quartered {{onion}}, chopped {{celery}}, {{parsley}} and {{thyme}}. Simmer for30–40 minutes until the beef and vegetables are tender.','Lift out the beef and keep covered and hot. Lift out the vegetables and press them through a sieve into a clean saucepan, adding a little cooking broth as needed to make a smooth purée. Reserve the rest of the broth for another meal, cooling it promptly in shallow containers.','Stir {{butter}}, {{cream}} and {{pepper}} into the purée and simmer gently for3–5 minutes, stirring. Add a little reserved hot broth if needed to give a pourable sauce.','Slice or portion the beef and place on a warm platter. Spoon the carrot sauce around it and serve immediately.'],'The source title and method require bouilli but omit beef from the ingredient list; a full1.2kg simmered-beef component is supplied. The listed onion, celery and herbs are incorporated into the sauce vegetables rather than silently omitted. A gill of cream becomes a modern120ml; this is a disclosed complete reconstruction of the abbreviated source method.','Main dishes')

r=add(92,'Carrots Sautés à la Créole with Chaurice',6,90,'Carrots finish slowly with Creole pork sausage, ham, tomato, herbs and a splash of white wine.',[carrot(900),water(1500),salt(3),butter(14),onion(150),I('scallions',60,'g','scallions, white and green parts finely sliced','Use the same weight of trimmed leek, cooking until tender.'),I('ham',30,'g','fully cooked ham, finely diced','Use the same weight of fully cooked smoked turkey.'),I('sausage',300,'g','raw pork chaurice, about three links','Use the same weight of raw spicy pork sausage; the Creole seasoning will differ.'),I('tomato',180,'g','ripe tomato, finely chopped with its juice','Use the same weight of canned chopped tomatoes.'),dict(stock(240),name='unsalted prepared beef bouillon'),I('wine',120,'ml','dry white wine','Use110ml unsalted broth plus10ml lemon juice for an alcohol-free variation.'),thyme(),parsley(5),bay(),garlic(3),pepper()],['Cut {{carrot}} into1cm rounds. Bring {{water}} and {{salt}} to a boil, add the carrots and cook for10–15 minutes until just tender. Drain.','Melt {{butter}} in a wide casserole. Add finely chopped {{onion}} and {{scallions}} and cook for5–7 minutes until lightly golden. Add {{ham}} and {{sausage}} and cook for3 minutes, turning the links.','Add {{thyme}}, {{parsley}}, {{bay}}, {{garlic}} and {{tomato}}. Cook for3 minutes, then add {{stock}}, {{wine}} and {{pepper}}. Bring to a gentle simmer and cook for10 minutes.','Add the carrots, cover loosely and simmer gently for25–30 minutes until the sausage reaches at least71°C (160°F) in the center and the carrots are very tender. Add water if the sauce becomes too thick.','Remove the bay leaf, slice the cooked sausage into portions and serve hot.'],'The source ingredient list says six sausages but its method says three; this adaptation chooses three links weighing300g total. The contradictory square-inch ham measures become a disclosed30g. The source shallots with greens and whites are interpreted as scallions. The initial90-minute carrot boil is shortened while retaining the long finished stew. Wine remains alcoholic after cooking.','Main dishes')

stuffbase=[carrot(800),water(1500),salt(4),I('filltomato',150,'g','ripe tomato, finely chopped for the filling','Use the same weight of canned chopped tomatoes, drained.'),I('fillonion',75,'g','onion, finely chopped for the filling','Use the same weight of shallot.'),I('fillparsley',5,'g','fresh parsley, chopped for the filling','Use the same weight of cilantro for a different flavor.'),oil(15,'filloil'),I('sardines',150,'g','canned sardines, drained weight','Use the same weight of drained canned mackerel; flavor differs.'),parsley(5)]
stuffsauce=[I('saucetomato',250,'g','ripe tomato, chopped for the sauce','Use the same weight of canned chopped tomatoes.'),I('sauceonion',75,'g','onion, finely chopped for the sauce','Use the same weight of shallot.'),oil(15,'sauceoil'),I('bread',5,'g','soft white breadcrumbs','Use the same weight of soft gluten-free breadcrumbs.'),I('achiote',.25,'tsp','ground annatto (achiote)','Use the same amount of sweet paprika for a different color and flavor.'),water(150,'saucewater')]
prep=['Choose thick {{carrot}}, cutting very long ones across into8–10cm lengths. Bring {{water}} and {{salt}} to a boil, add the carrots and cook for15–25 minutes until just tender enough to hollow without breaking. Drain and let cool briefly.','Cut a thin lengthwise lid from each carrot piece. Scoop out a shallow channel, leaving a sturdy wall. Finely chop the scooped carrot and keep it for the sauce; reserve the lids.','Heat {{filloil}} in a skillet and soften {{fillonion}} for5 minutes. Add {{filltomato}} and {{fillparsley}} and cook for8–10 minutes until thick. Fold in flaked {{sardines}} and warm for2 minutes.']
sauce=['Heat {{sauceoil}} in a saucepan, add {{sauceonion}} and cook for5 minutes. Add {{saucetomato}}, {{bread}}, {{achiote}}, {{saucewater}} and the reserved chopped carrot. Simmer for10–15 minutes until the onion is tender. Mash or blend to a thin sauce, adding a little water if needed.']
stuff=['Spoon the sardine filling into the hollow carrots, adding any extra filling to the sauce. Set the reserved carrot lids on top.']
finish=['Heat the oven to180°C (355°F). Spread the sauce in a shallow baking dish, place the stuffed carrots on it and cover. Bake for15–20 minutes until the filling reaches74°C (165°F).','Scatter {{parsley}} over the carrots and serve with the sauce.']
r=add(27,'Zanahorias Rellenas with Sardines and Tomato-Achiote Sauce',4,95,'Hollowed carrots hold a sardine, tomato and parsley filling and are served with a thin tomato-achiote sauce.',stuffbase+stuffsauce,prep+sauce+stuff+finish,'All missing amounts and the oven finish are supplied. A lengthwise lid and shallow channel replace a fragile fully hollow carrot; scooped carrot is used in the sauce. Extra filling joins the sauce rather than being wasted. The source vinegar-bay warming method and egg-fried option are separate complete variations.','Main dishes')
vitems=copy.deepcopy(stuffbase)+[vinegar(15),bay(),water(100,'bakewater')]
vprep=copy.deepcopy(prep);vprep[1]=vprep[1].replace('keep it for the sauce','reserve it for the baking dish')
vsteps=vprep+['Spoon the sardine filling into the carrot channels and set the lids on top. Place them in a shallow baking dish with the reserved chopped carrot and any extra filling.','Heat the oven to180°C (355°F). Add {{vinegar}}, {{bay}} and {{bakewater}} to the dish, cover and bake for15–20 minutes until the filling reaches74°C (165°F). Remove the bay leaf.','Scatter {{parsley}} over the carrots and serve with the light pan juices.']
variant(r,'vinegar-bay','Stuffed carrots with vinegar and bay',vitems,vsteps)
vitems=copy.deepcopy(r['ingredients'])+[eggs(2),I('coatflour',20,'g','all-purpose flour for coating','Use the same weight of a gluten-free plain flour blend.'),oil(200,'fryoil')]
vsteps=prep+sauce+stuff+['Keep the sauce warm. Secure each carrot lid with a wooden toothpick. Beat {{eggs}} in a shallow bowl and put {{coatflour}} on a plate. Lightly dust the closed carrots with flour, then coat with beaten egg.','Heat {{fryoil}} in a deep skillet to160–170°C (320–340°F), with the oil no more than one-third of the pan depth. Fry in small batches for3–4 minutes per side, turning gently, until the coating is golden and the filling reaches74°C (165°F). Drain on a rack.','Remove and count every toothpick before serving. Place the carrots on the warm sauce and scatter with {{parsley}}.']
variant(r,'egg-fried','Egg-coated fried stuffed carrots',vitems,vsteps)
r['notes']+=' The fried variation adds a light flour dusting to help the egg coat adhere. Frying oil is the pan quantity; not all is absorbed.'

def crayfish_items():return [I('crayfish',750,'g','fully cooked whole crayfish, chilled, about15 medium ones','Use the shells from fully cooked shell-on shrimp of similar total weight for a different shellfish butter.'),I('shellbutter',200,'g','unsalted butter for the shell infusion','Use the same weight of a block-style dairy-free butter alternative; flavor differs.')]
crayfish_steps=['Peel {{crayfish}}, collecting the tail and claw meat in a clean bowl. Refrigerate the meat promptly. Keep only the clean red shells; discard guts and any gills or other soft head contents. Crush the shells coarsely in a sturdy bag with a rolling pin, avoiding sharp fragments.','Melt {{shellbutter}} in a saucepan. Add the crushed shells and cook over low heat for10–15 minutes, stirring, until the butter is fragrant and colored; do not let it burn.','Pour through a fine sieve lined with two layers of damp clean muslin into a heatproof bowl. Press lightly with a spoon to recover the butter, without forcing shell fragments through. Discard the shells and check that the strained butter is free of grit.']
r=add(154,'Krebs-Butter (Crayfish Butter)',12,55,'Cooked crayfish shells gently infuse butter with shellfish flavor and a warm red-orange color.',crayfish_items(),crayfish_steps+['Use the strained butter immediately in a sauce, or cool it promptly in a shallow covered container and refrigerate within2 hours. Use within3 days or freeze. The reserved crayfish meat can be served separately or used in a pie or salad, keeping it refrigerated until needed.'],'The original recipe275 was visually checked: it gives20DEKAGRAMS of butter, not20teaspoons. This becomes200g. Fifteen unspecified crayfish become a modern750g purchase weight of fully cooked whole crayfish. Gentle shell infusion and cloth filtering replace pounding shells to a paste and chilling butter directly in water, reducing grit. Yield is roughly150–180g butter depending on straining, plus reserved meat.','Sauces')
r['source']+=' Primary scan verified: Wiener Kochbuch recipe275, printed page64, Internet Archive leaf64.'

r=add(144,'Erdäpfel-Pastete with Anchovies, Egg and Crayfish',10,150,'Puff pastry encloses a light potato filling layered with hard-cooked eggs, anchovies and crayfish, with crayfish-cream sauce alongside.',[I('potato',240,'g','peeled floury potatoes','Use the same weight of another floury potato variety.'),water(1000),butter(160),eggs(4),I('roll',80,'g','plain white bread roll without crust','Use the same weight of soft white bread without crust.'),milk(100),salt(2),I('pastry',500,'g','ready-to-use puff pastry, chilled','Use the same weight of dairy-free puff pastry; follow its baking instructions if they differ.'),I('grease',5,'g','unsalted butter for the dish','Use the same weight of a block-style dairy-free butter alternative.'),I('dustflour',10,'g','all-purpose flour for the dish and rolling','Use a small amount of rice flour for dusting.'),I('hardeggs',2,'','large fully hard-boiled eggs, peeled and chilled','Use three small fully hard-boiled eggs.'),I('anchovies',25,'g','oil-packed anchovy fillets, drained and finely chopped','Use the same weight of finely chopped capers for a different, fish-free seasoning; the pie still contains shellfish.'),I('eggwash',1,'','large egg for brushing the pastry','Use30ml milk instead; the pastry will be less glossy.')]+crayfish_items()+[I('infusedbutter',100,'g','strained crayfish butter reserved from the component in the steps','Use the measured butter made below, not an additional purchase.'),I('sauceflour',40,'g','all-purpose flour for the sauce','Use the same weight of a gluten-free blend labeled for sauces.'),cream(500),lemon(15)],crayfish_steps+['Measure {{infusedbutter}} from the strained butter for the sauce. Cool and refrigerate the remaining butter promptly for another meal. Keep the reserved crayfish meat refrigerated until assembling the pie.','Cut {{potato}} into small chunks. Bring {{water}} to a boil, add the potatoes and cook for15–20 minutes until tender. Drain thoroughly, mash smoothly and let cool until no longer warm.','Soak {{roll}} in {{milk}} for5 minutes, then squeeze out excess milk. Separate {{eggs}}, putting the whites in a clean grease-free bowl. Beat softened {{butter}} until fluffy, beat in the yolks one at a time and stir in the cooled potato, soaked bread and {{salt}}.','Beat the reserved whites to firm peaks and fold into the potato mixture. Heat the oven to200°C (390°F), with a metal baking tray inside. Grease a deep23cm pie dish with {{grease}} and dust lightly with part of {{dustflour}}.','Use the remaining dusting flour to roll {{pastry}} to about3–4mm thickness, making a base and lid. Line the dish with the base. Spread in half the potato mixture, layer with sliced {{hardeggs}}, {{anchovies}} and all the reserved crayfish meat, then cover with the remaining potato mixture.','Cover with the pastry lid, trim and seal the edges and cut several steam vents. Beat {{eggwash}} and brush a thin layer over the pastry, discarding unused egg wash. Bake on the hot tray for20 minutes, then reduce the oven to180°C (355°F) and bake for35–50 minutes more until the pastry is cooked through and the center reaches74°C (165°F). Shield the top loosely with foil if it browns too quickly.','While the pie bakes, melt the measured crayfish butter in a saucepan. Stir in {{sauceflour}} and cook for2 minutes. Gradually whisk in {{cream}} and simmer gently for5–7 minutes, stirring, until smooth. Stir in {{lemon}}; loosen with a little water if needed.','Let the pie rest for10 minutes, then serve slices with the warm sauce alongside. Keep the pie in its dish rather than turning it out.'],'The original recipe1086 is potato pastry with anchovies, hard-boiled eggs and crayfish. The German word Sardellen identifies anchovies. The scan contains no carrots or truffles. It lists16dekagrams butter,24dekagrams cooked potato,8dekagrams rolls and a halfLITER of cream. This adaptation uses240g peeled potato as a practical starting weight and supplies missing egg, anchovy, crayfish, milk and pastry amounts. The full same-book crayfish-butter component is included. Sauce flour is deliberately reduced from100g to40g for a pourable accompaniment; thin pastry replaces the finger-thick source pastry to bake through reliably. The source permits serving sauce separately, which is used here.','Main dishes')
next(i for i in r['ingredients'] if i['key']=='eggs')['substitution']='Use four large pasteurized shell eggs if preferred; the whites must remain separate and able to whip.'
r['source']+=' Primary scan verified: Wiener Kochbuch recipe1086, printed page247, leaf247; complete component recipe275, page64. Original title and source text remain in the immutable record.'

assert len(newids)==14,len(newids)
# Apply readable spacing to this batch only; never rewrite source URLs, IDs or original text.
import re
def spaced(s):return re.sub(r'(?<=\d)(?=[A-Za-z])',' ',re.sub(r'(?<=[A-Za-z])(?=\d)',' ',s))
for id in newids:
 r=records[id]['recipe']
 for key in ['title','description','notes']:r[key]=spaced(r[key])
 for version in [r]+r.get('variants',[]):
  version['steps']=[spaced(t) for t in version['steps']]
  for item in version['ingredients']:
   for key in ['name','substitution']:item[key]=spaced(item[key])
 r['source']+=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Egg handling: https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety .'
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full method reviewed; ambiguous ingredients checked against original pages, missing components and measured modern choices supplied','repair-batch-014.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=0,totalOverrides=len(records),totalAliases=len(aliases))))

